def parse_duration(text: str) -> float:
    if not text or not text.startswith('P'):
        raise ValueError("Invalid duration format")

    # Remove the 'P' prefix
    text = text[1:]

    # Split by 'T' to separate date and time parts
    if 'T' in text:
        date_part, time_part = text.split('T', 1)
        if not time_part:
            raise ValueError("T must be followed by at least one time component")
    else:
        date_part = text
        time_part = ""

    total_seconds = 0.0

    # Parse date part (weeks or days)
    if date_part:
        if 'W' in date_part:
            if 'D' in date_part:
                raise ValueError("Cannot have both weeks and days")
            # Extract weeks
            if date_part.count('W') != 1 or not date_part.endswith('W'):
                raise ValueError("Invalid weeks format")
            weeks_str = date_part[:-1]
            if not weeks_str or not is_valid_number(weeks_str):
                raise ValueError("Invalid weeks value")
            weeks = parse_number(weeks_str)
            total_seconds += weeks * 7 * 86400
        elif 'D' in date_part:
            # Extract days
            if date_part.count('D') != 1 or not date_part.endswith('D'):
                raise ValueError("Invalid days format")
            days_str = date_part[:-1]
            if not days_str or not is_valid_number(days_str):
                raise ValueError("Invalid days value")
            days = parse_number(days_str)
            total_seconds += days * 86400
        else:
            raise ValueError("Invalid date part")

    # Parse time part (hours, minutes, seconds)
    if time_part:
        remaining = time_part

        # Parse hours
        if 'H' in remaining:
            idx = remaining.index('H')
            hours_str = remaining[:idx]
            if not hours_str or not is_valid_number(hours_str):
                raise ValueError("Invalid hours value")
            hours = parse_number(hours_str)
            total_seconds += hours * 3600
            remaining = remaining[idx+1:]

        # Parse minutes
        if 'M' in remaining:
            idx = remaining.index('M')
            minutes_str = remaining[:idx]
            if not minutes_str or not is_valid_number(minutes_str):
                raise ValueError("Invalid minutes value")
            minutes = parse_number(minutes_str)
            total_seconds += minutes * 60
            remaining = remaining[idx+1:]

        # Parse seconds
        if 'S' in remaining:
            idx = remaining.index('S')
            seconds_str = remaining[:idx]
            if not seconds_str or not is_valid_number(seconds_str):
                raise ValueError("Invalid seconds value")
            seconds = parse_number(seconds_str)
            total_seconds += seconds
            remaining = remaining[idx+1:]

        # Check if there's any leftover text
        if remaining:
            raise ValueError("Invalid time format")

    # At least one component must be present
    if total_seconds == 0 and not date_part and not time_part:
        raise ValueError("At least one component must be present")

    return total_seconds


def is_valid_number(s: str) -> bool:
    """Check if string is a valid non-negative number (int or decimal)."""
    if not s:
        return False

    # Replace comma with period for decimal separator
    s = s.replace(',', '.')

    # Check if it contains only digits and at most one decimal point
    parts = s.split('.')
    if len(parts) > 2:
        return False

    for part in parts:
        if not part:
            return False
        if not part.isdigit():
            return False

    return True


def parse_number(s: str) -> float:
    """Parse a number string (int or decimal) to float."""
    s = s.replace(',', '.')
    return float(s)

